import{_ as i,o as a,c as t,a2 as n}from"./chunks/framework.YT-FC_Xx.js";const g=JSON.parse('{"title":"安装 agent","description":"","frontmatter":{},"headers":[],"relativePath":"guide/agent.md","filePath":"guide/agent.md","lastUpdated":1792840431000}'),e={name:"guide/agent.md"};function l(h,s,p,r,d,k){return a(),t("div",null,[...s[0]||(s[0]=[n(`<h1 id="安装-agent" tabindex="-1">安装 agent <a class="header-anchor" href="#安装-agent" aria-label="Permalink to &quot;安装 agent&quot;">​</a></h1><p>agent 装在要搭节点或当中转的服务器上：连接面板，负责转发流量、下载和运行内核、测延迟和回程。</p><h2 id="准备" tabindex="-1">准备 <a class="header-anchor" href="#准备" aria-label="Permalink to &quot;准备&quot;">​</a></h2><ul><li>Linux amd64 / arm64，root 权限（Alpine 也支持）</li><li>面板 <strong>设置 → 基本</strong> 里已填好“面板后端地址”</li><li>搭节点的服务器建议安装 nftables（<code>apt install nftables</code>）：入站流量统计、白名单、订阅流量上限和 Hysteria2 端口跳跃依赖它；没有时服务器照常工作，只是没有这些功能</li></ul><h2 id="用面板生成的命令安装-推荐" tabindex="-1">用面板生成的命令安装（推荐） <a class="header-anchor" href="#用面板生成的命令安装-推荐" aria-label="Permalink to &quot;用面板生成的命令安装（推荐）&quot;">​</a></h2><ol><li><strong>服务器</strong> 页新建服务器，点击 <strong>安装</strong>，在弹出的窗口里选 <strong>一键脚本</strong> 或 <strong>Docker</strong>，点 <strong>复制</strong></li><li>到服务器上以 root 执行，等服务器状态变为 <strong>在线</strong></li></ol><h2 id="用-docker-安装" tabindex="-1">用 Docker 安装 <a class="header-anchor" href="#用-docker-安装" aria-label="Permalink to &quot;用 Docker 安装&quot;">​</a></h2><p>服务器已装好 Docker 时，可以用容器运行 agent。在安装窗口切到 <strong>Docker</strong>，复制的命令形如：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> flux_agent</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/dev/null</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> 2&gt;&amp;1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --name</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> flux_agent</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --restart</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> unless-stopped</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --network</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> host</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --cap-add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> NET_ADMIN</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -v</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc/flux_agent:/etc/flux_agent</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> FLUX_AGENT_ADDR=</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">面板地</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">址</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> FLUX_AGENT_SECRET=</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">密</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">钥</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  ghcr.io/kure29/flux-agent:</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">版</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">本</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span></code></pre></div><ul><li><code>--network host</code>：转发和入站要按需监听任意端口，必须用宿主机网络</li><li><code>--cap-add NET_ADMIN</code>：入站流量统计和白名单要用 nftables</li><li><code>/etc/flux_agent</code>：配置、下载的内核和 agent 程序都在这里，删掉容器重建不会丢</li><li><code>--restart unless-stopped</code>：不能去掉，面板一键升级靠它把容器拉起来</li><li>不要和一键脚本安装的 agent 同时运行，二者会抢端口；换成 Docker 前先在原机器上卸载脚本版</li></ul><p><strong>升级</strong>：和脚本安装一样，在 <strong>服务器</strong> 页点 <strong>升级</strong>，agent 下载新版本替换数据目录里的程序后自动重启容器；也可以拉取新版本镜像后重新执行安装命令，镜像里的版本会覆盖数据目录里的程序。</p><p><strong>调优</strong>：容器默认改不了宿主机内核参数，要用调优需要把 <code>--cap-add NET_ADMIN</code> 换成 <code>--privileged</code>；宿主机重启后需要在面板重新应用一次。</p><p><strong>查看日志</strong>：<code>docker logs -f flux_agent</code></p><h2 id="服务器调优" tabindex="-1">服务器调优 <a class="header-anchor" href="#服务器调优" aria-label="Permalink to &quot;服务器调优&quot;">​</a></h2><p><strong>服务器</strong> 页的服务器卡片上点 <strong>调优</strong>（列表视图在操作菜单里），先填这台服务器的 <strong>带宽</strong>（Mbps，套餐带宽）和 <strong>主要线路延迟</strong>（ms，到主要用户的延迟，跨境线路一般 150 左右），面板按这两个数和服务器内存算出参数，下面显示当前值和要改成的值，可调的项目默认全部勾选：</p><table tabindex="0"><thead><tr><th>项目</th><th>作用</th></tr></thead><tbody><tr><td>BBR 拥塞控制</td><td>高延迟、有丢包的线路上明显提速，需要内核 4.9 以上；模块开机自动加载</td></tr><tr><td>按带宽和延迟设缓冲区</td><td>单连接缓冲区上限 = 带宽 × 延迟 × 2 + 2MB，最低 4MB，最多内存的 1/32、256MB；TCP 总内存按内存的 1/16、1/8、1/4 设三档；连接起始缓冲区 1MB</td></tr><tr><td>TCP 连接优化</td><td>Fast Open、空闲后不降速、自动探测 MTU、15 秒回收关闭的连接、复用 TIME_WAIT、10 分钟保活、SYN Cookies</td></tr><tr><td>高并发</td><td>连接多时不丢新连接；出站端口范围 10000–65535，中转发起的连接多时不缺端口</td></tr><tr><td>IPv4 转发</td><td>内核转发（nftables 端口转发）需要</td></tr><tr><td>文件句柄上限</td><td>允许打开更多连接和文件</td></tr></tbody></table><ul><li>点 <strong>应用</strong> 后立即生效，并写入 <code>/etc/sysctl.d/99-flyx-tuning.conf</code>，重启后保持；带宽和延迟会记住，下次打开调优自动填上</li><li>只会调大的上限类参数（缓冲区、TCP 总内存、队列、句柄数）如果服务器本来就更高，保持原值不动；面板之前调过的值，换了带宽 / 延迟后会按新值改（包括改小）</li><li>之后取消勾选某一项再应用，这一项会恢复成调优前的值；<strong>恢复默认</strong> 撤销全部调优</li><li>系统不支持的项（比如内核没有 BBR）会跳过并提示</li><li>需要 agent 为 3.3.10 及以上；按带宽和延迟计算需要 3.3.42 及以上，更旧的版本缓冲区用固定的 64MB</li><li>计算方法参考了 <a href="https://github.com/Kylin010/tcpfit" target="_blank" rel="noreferrer">tcpfit</a>。没有采用它的实测带宽、出向整形和初始拥塞窗口（会改默认路由）</li></ul><h2 id="国内服务器安装慢" tabindex="-1">国内服务器安装慢 <a class="header-anchor" href="#国内服务器安装慢" aria-label="Permalink to &quot;国内服务器安装慢&quot;">​</a></h2><p>安装脚本、agent 程序、Xray / sing-box 等内核和分流数据都来自 GitHub，国内服务器直接下载很慢，默认经公共加速站下载，速度看加速站当时的情况。</p><p>面板在海外时，可以让服务器改从面板下载：<strong>设置</strong> → <strong>服务器与监控</strong> → 打开 <strong>GitHub 加速</strong> → 加速地址点 <strong>面板中转</strong>，保存。地址是“面板后端地址”加上 <code>/api/v1/open_api/gh</code>，例如 <code>http://1.2.3.4:6365/api/v1/open_api/gh</code>（按钮会自动填，带 <code>https://</code> 的地址请核对一下）。之后：</p><ul><li>新生成的安装命令、服务器升级、内核安装和分流数据更新都经面板下载，服务器只需要能连上面板</li><li>面板第一次下载某个文件时从 GitHub 拉取并缓存在数据目录的 <code>github-cache</code> 里（最多约 2 GB，超出自动清理最早的），之后直接给服务器，多个服务器只下载一次</li><li>只提供面板用到的仓库（本项目、Xray、sing-box、shadow-tls 和分流数据），不能当通用 GitHub 代理用</li><li>面板自己升级时仍直接访问 GitHub</li></ul><p>面板也在国内、同样访问不了 GitHub 时，继续用公共加速站，或者换成你自己的加速地址。</p><h2 id="手动安装" tabindex="-1">手动安装 <a class="header-anchor" href="#手动安装" aria-label="Permalink to &quot;手动安装&quot;">​</a></h2><p>在服务器上运行：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -L</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/kure29/flyx/releases/latest/download/install.sh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install.sh</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">chmod</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> +x</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install.sh</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./install.sh</span></span></code></pre></div><p>Alpine Linux 最小化安装若未包含 <code>curl</code>，可使用系统自带的 <code>wget</code> 下载：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">wget</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -O</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install.sh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/kure29/flyx/releases/latest/download/install.sh</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">chmod</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> +x</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install.sh</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./install.sh</span></span></code></pre></div><p>脚本会在 Alpine 上自动安装 Bash、<code>curl</code> 和 CA 证书，并使用 OpenRC 注册、启动和管理 <code>flux_agent</code> 服务；其他受支持的 Linux 发行版继续使用 systemd。</p><p><strong>安装过程中会提示输入：</strong></p><ul><li><strong>服务器地址</strong>: 面板端的通信地址（通常是 <code>http://&lt;面板IP&gt;:&lt;后端端口&gt;</code>，例如 <code>http://1.2.3.4:6365</code>）。</li><li><strong>密钥</strong>: 服务器页里该服务器的密钥。</li></ul><p>或者直接使用带参数的命令（适用于自动化部署）：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 替换 &lt;面板地址&gt; 和 &lt;密钥&gt;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./install.sh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -a</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;http://1.2.3.4:6365&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;your_node_secret&quot;</span></span></code></pre></div><h2 id="验证安装" tabindex="-1">验证安装 <a class="header-anchor" href="#验证安装" aria-label="Permalink to &quot;验证安装&quot;">​</a></h2><p>安装完成后，服务会自动启动。</p><ul><li>systemd 查看状态: <code>systemctl status flux_agent</code></li><li>Alpine/OpenRC 查看状态: <code>rc-service flux_agent status</code></li><li>Docker 查看状态: <code>docker ps -f name=flux_agent</code></li><li>回到面板 <strong>服务器</strong> 页，该服务器状态应显示为 <strong>在线</strong></li></ul><p>服务器离线的排查见 <a href="./faq#服务器显示离线">常见问题</a>。</p><h2 id="升级-agent" tabindex="-1">升级 agent <a class="header-anchor" href="#升级-agent" aria-label="Permalink to &quot;升级 agent&quot;">​</a></h2><p><strong>服务器</strong> 页选择服务器 → <strong>升级</strong>（可以多选批量升级），留空版本即使用最新版。新功能（例如回程检测）需要 agent 跟面板一起升级，见 <a href="./upgrade#agent-升级">升级</a>。</p>`,38)])])}const c=i(e,[["render",l]]);export{g as __pageData,c as default};
